#!/usr/bin/env python3
"""Merge a custom menu item into a WeChat Official Account menu.

WeChat's menu API replaces the complete menu; it has no append operation. This
script reads the current menu first, adds one idempotent CLICK button, writes a
backup, and only then submits the complete merged menu.

The default config path is ``wechat-draft/config.json`` and uses the same
``app_id``, ``app_secret`` and optional ``api_base`` fields as
``scripts/wechat_draft.py``.

Examples:
  python scripts/wechat_menu.py --dry-run
  python scripts/wechat_menu.py --yes
  python scripts/wechat_menu.py --parent "更多" --name "获取注册码" --yes
"""

from __future__ import annotations

import argparse
import json
import sys
from datetime import datetime, timezone
from pathlib import Path
from urllib.error import HTTPError, URLError
from urllib.parse import urlencode
from urllib.request import Request, urlopen


DEFAULT_API_BASE = "https://api.weixin.qq.com"
DEFAULT_CONFIG = Path(__file__).resolve().parent.parent / "wechat-draft" / "config.json"
DEFAULT_BACKUP_DIR = Path(__file__).resolve().parent.parent / "wechat-draft" / "menu-backups"
DEFAULT_NAME = "注册码"
DEFAULT_KEY = "GET_REGISTRATION_CODE"
REQUEST_TIMEOUT_SECONDS = 60
NO_MENU_ERROR_CODE = 46003
MAX_FIRST_LEVEL_BUTTONS = 3
MAX_SECOND_LEVEL_BUTTONS = 5
MAX_FIRST_LEVEL_NAME_LENGTH = 4
MAX_SECOND_LEVEL_NAME_LENGTH = 8
MAX_KEY_BYTES = 128


class WeChatAPIError(RuntimeError):
    def __init__(self, endpoint: str, payload: object):
        self.endpoint = endpoint
        self.payload = payload
        if isinstance(payload, dict):
            message = f"errcode={payload.get('errcode')}, errmsg={payload.get('errmsg')}"
        else:
            message = str(payload)
        super().__init__(f"WeChat API {endpoint} failed: {message}")


def api_request(
    url: str,
    endpoint: str,
    data: bytes | None = None,
    allowed_error_codes: set[int] | None = None,
) -> dict:
    request = Request(
        url,
        data=data,
        headers={"Content-Type": "application/json; charset=utf-8"} if data is not None else {},
        method="POST" if data is not None else "GET",
    )
    try:
        with urlopen(request, timeout=REQUEST_TIMEOUT_SECONDS) as response:
            raw = response.read()
    except HTTPError as error:
        raw = error.read()
        try:
            payload = json.loads(raw.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError):
            payload = raw.decode("utf-8", errors="replace")
        raise WeChatAPIError(endpoint, payload) from error
    except URLError as error:
        raise RuntimeError(f"request failed for {endpoint}: {error.reason}") from error

    try:
        payload = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as error:
        raise RuntimeError(f"WeChat API returned invalid JSON from {endpoint}") from error
    if not isinstance(payload, dict):
        raise WeChatAPIError(endpoint, payload)

    try:
        error_code = int(payload.get("errcode", 0) or 0)
    except (TypeError, ValueError) as error:
        raise WeChatAPIError(endpoint, payload) from error
    if error_code != 0 and error_code not in (allowed_error_codes or set()):
        raise WeChatAPIError(endpoint, payload)
    return payload


def read_config(config_path: Path) -> dict[str, str]:
    try:
        config = json.loads(config_path.read_text(encoding="utf-8-sig"))
    except FileNotFoundError as error:
        raise FileNotFoundError(f"config not found: {config_path}") from error
    except json.JSONDecodeError as error:
        raise ValueError(f"invalid JSON config: {config_path}") from error
    if not isinstance(config, dict):
        raise ValueError(f"config must be a JSON object: {config_path}")

    def string_value(key: str) -> str:
        value = config.get(key, "")
        return value.strip() if isinstance(value, str) else ""

    app_id = string_value("app_id")
    app_secret = string_value("app_secret")
    if not app_id or not app_secret:
        raise ValueError(f"config must contain app_id and app_secret: {config_path}")
    return {"app_id": app_id, "app_secret": app_secret, "api_base": string_value("api_base")}


def get_access_token(app_id: str, app_secret: str, api_base: str) -> str:
    query = urlencode({"grant_type": "client_credential", "appid": app_id, "secret": app_secret})
    payload = api_request(f"{api_base}/cgi-bin/token?{query}", "cgi-bin/token")
    token = payload.get("access_token")
    if not isinstance(token, str) or not token:
        raise RuntimeError("WeChat API did not return access_token")
    return token


def get_current_menu(api_base: str, token: str) -> tuple[dict, list[dict]]:
    payload = api_request(
        f"{api_base}/cgi-bin/menu/get?{urlencode({'access_token': token})}",
        "cgi-bin/menu/get",
        allowed_error_codes={NO_MENU_ERROR_CODE},
    )
    try:
        error_code = int(payload.get("errcode", 0) or 0)
    except (TypeError, ValueError) as error:
        raise WeChatAPIError("cgi-bin/menu/get", payload) from error
    if error_code == NO_MENU_ERROR_CODE:
        return payload, []

    conditional_menu = payload.get("conditionalmenu")
    if conditional_menu:
        raise ValueError(
            "the account has conditional menus; refusing to replace them because "
            "cgi-bin/menu/create cannot preserve conditional menu rules"
        )

    menu = payload.get("menu")
    if menu is None:
        return payload, []
    if not isinstance(menu, dict) or not isinstance(menu.get("button"), list):
        raise ValueError("WeChat returned a menu without a valid button list")
    buttons = menu["button"]
    if not all(isinstance(button, dict) for button in buttons):
        raise ValueError("WeChat returned an invalid menu button")
    return payload, buttons


def validate_existing_buttons(buttons: list[dict], level: int = 0) -> None:
    if level == 0 and len(buttons) > MAX_FIRST_LEVEL_BUTTONS:
        raise ValueError("WeChat returned more than 3 first-level menu buttons")
    if level == 1 and len(buttons) > MAX_SECOND_LEVEL_BUTTONS:
        raise ValueError("WeChat returned more than 5 second-level menu buttons")

    for button in buttons:
        sub_buttons = button.get("sub_button")
        if sub_buttons is None:
            continue
        if not isinstance(sub_buttons, list) or not all(isinstance(item, dict) for item in sub_buttons):
            raise ValueError("WeChat returned an invalid sub_button list")
        validate_existing_buttons(sub_buttons, level + 1)


def iter_buttons(buttons: list[dict]):
    for button in buttons:
        yield button
        sub_buttons = button.get("sub_button")
        if isinstance(sub_buttons, list):
            yield from iter_buttons(sub_buttons)


def validate_new_button(name: str, key: str, nested: bool) -> None:
    if not name.strip():
        raise ValueError("menu name cannot be empty")
    max_name_length = MAX_SECOND_LEVEL_NAME_LENGTH if nested else MAX_FIRST_LEVEL_NAME_LENGTH
    if len(name) > max_name_length:
        level = "second-level" if nested else "first-level"
        raise ValueError(f"{level} menu name must be at most {max_name_length} characters: {name!r}")
    if not key.strip():
        raise ValueError("menu key cannot be empty")
    if len(key.encode("utf-8")) > MAX_KEY_BYTES:
        raise ValueError("menu key must be at most 128 UTF-8 bytes")


def merge_registration_button(buttons: list[dict], name: str, key: str, parent: str | None) -> tuple[list[dict], bool, str]:
    validate_existing_buttons(buttons)
    for button in iter_buttons(buttons):
        existing_key = button.get("key")
        if existing_key == key:
            if button.get("type") != "click":
                raise ValueError(f"menu key already exists with type {button.get('type')!r}: {key}")
            return buttons, False, "existing menu button"
        if button.get("name") == name:
            raise ValueError(f"menu name already exists; refusing to create a duplicate: {name}")

    candidate = {"type": "click", "name": name, "key": key}
    if parent is not None:
        matches = [button for button in buttons if button.get("name") == parent]
        if len(matches) != 1:
            raise ValueError(f"parent first-level menu not found uniquely: {parent}")
        target = matches[0]
        sub_buttons = target.get("sub_button")
        if not isinstance(sub_buttons, list):
            raise ValueError(f"parent menu is not an existing submenu: {parent}")
        if len(sub_buttons) >= MAX_SECOND_LEVEL_BUTTONS:
            raise ValueError(f"parent submenu already has 5 buttons: {parent}")
        validate_new_button(name, key, nested=True)
        target["sub_button"].append(candidate)
        return buttons, True, f"submenu {parent!r}"

    validate_new_button(name, key, nested=False)
    if len(buttons) >= MAX_FIRST_LEVEL_BUTTONS:
        raise ValueError(
            "all 3 first-level menu slots are occupied; pass --parent with an existing submenu "
            "to preserve the current menu"
        )
    buttons.append(candidate)
    return buttons, True, "first-level menu"


def build_menu_payload(buttons: list[dict]) -> dict[str, list[dict]]:
    return {"button": buttons}


def save_backup(backup_dir: Path, payload: dict) -> Path:
    backup_dir.mkdir(parents=True, exist_ok=True)
    timestamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ")
    backup_path = backup_dir / f"menu-{timestamp}.json"
    suffix = 1
    while backup_path.exists():
        backup_path = backup_dir / f"menu-{timestamp}-{suffix}.json"
        suffix += 1
    backup_path.write_text(json.dumps(payload, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    return backup_path


def create_menu(api_base: str, token: str, payload: dict) -> None:
    api_request(
        f"{api_base}/cgi-bin/menu/create?{urlencode({'access_token': token})}",
        "cgi-bin/menu/create",
        data=json.dumps(payload, ensure_ascii=False, separators=(",", ":")).encode("utf-8"),
    )


def print_menu(title: str, payload: dict) -> None:
    print(title)
    print(json.dumps(payload, ensure_ascii=False, indent=2))


def main() -> int:
    parser = argparse.ArgumentParser(description="Add a WeChat menu button without dropping the current menu.")
    parser.add_argument("--config", type=Path, default=DEFAULT_CONFIG, help="config.json path")
    parser.add_argument("--backup-dir", type=Path, default=DEFAULT_BACKUP_DIR, help="directory for pre-change menu backups")
    parser.add_argument("--name", default=DEFAULT_NAME, help="new menu button name (default: 注册码)")
    parser.add_argument("--key", default=DEFAULT_KEY, help="CLICK event key (default: GET_REGISTRATION_CODE)")
    parser.add_argument("--parent", help="existing first-level submenu name; use when all top-level slots are full")
    parser.add_argument("--api-base", default=None, help="override WeChat API base URL")
    parser.add_argument("--dry-run", action="store_true", help="read and preview the merged menu without submitting it")
    parser.add_argument("--yes", action="store_true", help="submit without the interactive confirmation prompt")
    args = parser.parse_args()

    config = read_config(args.config.expanduser().resolve())
    api_base = str(args.api_base or config.get("api_base") or DEFAULT_API_BASE).rstrip("/")
    token = get_access_token(config["app_id"], config["app_secret"], api_base)
    current_payload, current_buttons = get_current_menu(api_base, token)
    merged_buttons, changed, location = merge_registration_button(
        json.loads(json.dumps(current_buttons)), args.name.strip(), args.key.strip(), args.parent
    )
    proposed_payload = build_menu_payload(merged_buttons)

    print_menu("Current menu:", build_menu_payload(current_buttons))
    print_menu("Proposed menu:", proposed_payload)
    if not changed:
        print("No change: the CLICK key already exists; nothing was submitted.")
        return 0
    print(f"Will add {args.name!r} as a {location} CLICK button with key {args.key!r}.")

    if args.dry_run:
        print("Dry run: nothing was submitted.")
        return 0
    if not args.yes:
        if not sys.stdin.isatty():
            raise ValueError("refusing to submit from a non-interactive shell; pass --yes explicitly")
        answer = input("Submit this complete menu to WeChat? [y/N] ").strip().lower()
        if answer not in {"y", "yes"}:
            print("Cancelled: nothing was submitted.")
            return 0

    backup_path = save_backup(args.backup_dir.expanduser().resolve(), current_payload)
    create_menu(api_base, token, proposed_payload)
    print(json.dumps({"created": True, "backup": str(backup_path), "location": location}, ensure_ascii=False, indent=2))
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except (FileNotFoundError, ValueError, RuntimeError, WeChatAPIError) as error:
        print(f"error: {error}", file=sys.stderr)
        raise SystemExit(1)

